----------------------------------------------------------------------
-- Hyprland Unified Configuration Bridge
-- Authoritative Source: /home/nithin/.config/hypr/hyprland.conf
--
-- This bridge dynamically translates ~/.config/hypr/hyprland.conf
-- into Hyprland 0.57 hl.* Lua API calls.
-- All desktop configuration is owned exclusively by hyprland.conf.
-- Do not edit this file manually.
----------------------------------------------------------------------

local CONF_PATH = "/home/nithin/.config/hypr/hyprland.conf"

local function trim(s)
    if not s then return "" end
    return s:match("^%s*(.-)%s*$")
end

local function strip_comments(line)
    local trimmed = trim(line)
    if #trimmed == 0 or trimmed:sub(1, 1) == "#" then
        return nil
    end
    -- Strip trailing comment (unless in quotes)
    local in_quotes = false
    local q_char = nil
    local out = {}
    for i = 1, #trimmed do
        local c = trimmed:sub(i, i)
        if (c == '"' or c == "'") and not in_quotes then
            in_quotes = true
            q_char = c
            table.insert(out, c)
        elseif in_quotes and c == q_char then
            in_quotes = false
            table.insert(out, c)
        elseif not in_quotes and c == "#" then
            break
        else
            table.insert(out, c)
        end
    end
    local res = trim(table.concat(out))
    if #res == 0 then return nil end
    return res
end

local vars = {
    mainMod     = "SUPER",
    terminal    = "/usr/bin/kitty",
    fileManager = "/usr/bin/dolphin",
    menu        = "nwg-drawer -wm uwsm -term kitty -fm dolphin",
}

local function sanitize_path(p)
    local seen = {}
    local out = {}
    local current_sys_path = "/home/nithin/.local/bin:/usr/local/sbin:/usr/local/bin:/usr/bin:/bin"
    p = p:gsub("%$PATH", current_sys_path)
    p = p:gsub("%$([%w_]+)", function(k) return os.getenv(k) or "" end)
    for part in (p .. ":"):gmatch("([^:]*):") do
        local trimmed = trim(part)
        if #trimmed > 0 and trimmed ~= "$PATH" and not seen[trimmed] then
            seen[trimmed] = true
            table.insert(out, trimmed)
        end
    end
    for _, standard in ipairs({ "/usr/local/bin", "/usr/bin", "/bin" }) do
        if not seen[standard] then
            seen[standard] = true
            table.insert(out, standard)
        end
    end
    return table.concat(out, ":")
end

-- Ensure clean PATH is set in Hyprland
pcall(function() hl.env("PATH", "/home/nithin/.local/bin:/usr/local/sbin:/usr/local/bin:/usr/bin:/bin") end)

local function resolve_vars(str)
    if not str then return "" end
    return (str:gsub("%$([%w_]+)", function(k)
        return vars[k] or os.getenv(k) or ("$" .. k)
    end))
end

local function parse_value(v)
    v = trim(v)
    if v == "true" or v == "yes" then return true end
    if v == "false" or v == "no" then return false end
    local num = tonumber(v)
    if num ~= nil then return num end
    return v
end

local function parse_color_gradient(val)
    val = trim(val)
    local colors = {}
    local angle = nil
    for part in val:gmatch("%S+") do
        if part:match("^rgba?%(") or part:match("^0x") or part:match("^#") then
            table.insert(colors, part)
        elseif part:match("^(%d+)deg$") then
            angle = tonumber(part:match("^(%d+)deg$"))
        end
    end
    if #colors > 1 or angle ~= nil then
        return { colors = colors, angle = angle or 0 }
    elseif #colors == 1 then
        return colors[1]
    end
    return val
end

local function split_commas(str)
    local t = {}
    for match in (str .. ","):gmatch("([^,]*),") do
        table.insert(t, trim(match))
    end
    return t
end

-- Tables to collect parsed configurations
local config_sections = {}
local registered_binds = {}
local monitor_loaded = false

local KEY_ALIASES = {
    RETURN = "Return", return_key = "Return", enter = "Return", Enter = "Return", ENTER = "Return",
    left = "Left", right = "Right", up = "Up", down = "Down",
    print = "Print", PRINT = "Print",
    esc = "Escape", ESC = "Escape", escape = "Escape", Escape = "Escape",
    backspace = "BackSpace", BackSpace = "BackSpace", BACKSPACE = "BackSpace",
    tab = "Tab", TAB = "Tab",
    space = "space", SPACE = "space",
    delete = "Delete", DELETE = "Delete",
}

local function register_binding(btype, mods_raw, key_raw, disp_raw, arg_raw)
    local mods = trim(resolve_vars(mods_raw))
    local raw_key = trim(resolve_vars(key_raw))
    local disp = trim(resolve_vars(disp_raw))
    local arg = trim(resolve_vars(arg_raw))

    if #raw_key == 0 then return end

    local key = KEY_ALIASES[raw_key] or raw_key

    local key_str = ""
    if #mods > 0 then
        mods = mods:gsub("%s+", " + ")
        key_str = mods .. " + " .. key
    else
        key_str = key
    end

    -- Avoid duplicate bindings
    local bind_signature = btype .. ":" .. key_str
    if registered_binds[bind_signature] then
        return
    end
    registered_binds[bind_signature] = true

    local opts = {}
    if btype:find("e") then opts.repeating = true end
    if btype:find("l") then opts.locked = true end
    if btype:find("m") then opts.mouse = true end
    if btype:find("r") then opts.release = true end

    local action = nil

    if btype:find("m") then
        if disp == "movewindow" then
            action = hl.dsp.window.drag()
        elseif disp == "resizewindow" then
            action = hl.dsp.window.resize()
        end
    elseif disp == "exec" then
        action = hl.dsp.exec_cmd(arg)
    elseif disp == "killactive" then
        action = hl.dsp.window.close()
    elseif disp == "pseudo" then
        action = hl.dsp.window.pseudo()
    elseif disp == "fullscreen" then
        action = hl.dsp.window.fullscreen()
    elseif disp == "togglefloating" then
        action = hl.dsp.window.float({ action = "toggle" })
    elseif disp == "layoutmsg" then
        if arg:match("togglesplit") then
            action = hl.dsp.layout("togglesplit")
        else
            action = hl.dsp.layout(arg)
        end
    elseif disp == "movefocus" then
        local dir_map = { l = "left", r = "right", u = "up", d = "down", left = "left", right = "right", up = "up", down = "down" }
        local dir = dir_map[arg] or arg
        action = hl.dsp.focus({ direction = dir })
    elseif disp == "workspace" then
        if arg == "e+1" or arg == "e-1" then
            action = hl.dsp.focus({ workspace = arg })
        else
            local num = tonumber(arg)
            action = hl.dsp.focus({ workspace = num or arg })
        end
    elseif disp == "movetoworkspace" then
        local num = tonumber(arg)
        action = hl.dsp.window.move({ workspace = num or arg })
    elseif disp == "togglespecialworkspace" then
        action = hl.dsp.workspace.toggle_special(arg ~= "" and arg or "magic")
    else
        action = hl.dsp.exec_cmd("hyprctl dispatch " .. disp .. " " .. arg)
    end

    local is_return = (key == "Return" or raw_key == "RETURN" or raw_key == "Return" or raw_key == "enter" or raw_key == "Enter")
    if is_return and disp == "exec" and (arg:match("kitty") or arg == vars.terminal) then
        local cmd = (arg == "kitty" and "/usr/bin/kitty" or arg)
        action = hl.dsp.exec_cmd("sh -c 'echo \"[" .. os.date("%Y-%m-%d %H:%M:%S") .. "] SUPER+ENTER physically triggered\" >> /tmp/hypr_enter_debug.log; exec " .. cmd .. "'")
    end

    if action then
        pcall(function()
            if opts.locked or opts.repeating or opts.mouse or opts.release then
                hl.bind(key_str, action, opts)
            else
                hl.bind(key_str, action)
            end
        end)
    end
end

local function apply_rule(rule_type, rule_data)
    local name = rule_data.name or "unnamed-rule"
    local match = {}
    local props = { name = name, match = match }

    for k, v in pairs(rule_data) do
        if k:match("^match:") then
            local prop = k:match("^match:(.+)$")
            match[prop] = v
        elseif k ~= "name" then
            props[k] = v
        end
    end

    if rule_type == "windowrule" then
        local ok, err = pcall(function() hl.window_rule(props) end)
        if not ok then error("[bridge] Invalid windowrule: " .. tostring(err), 0) end
    elseif rule_type == "layerrule" then
        local ok, err = pcall(function() hl.layer_rule(props) end)
        if not ok then error("[bridge] Invalid layerrule: " .. tostring(err), 0) end
    elseif rule_type == "device" then
        local ok, err = pcall(function() hl.device(rule_data) end)
        if not ok then error("[bridge] Invalid device config: " .. tostring(err), 0) end
    end
end

-- Recursive parser for hyprland.conf and any sourced files
local function parse_file(path)
    -- Expand ~ if present
    if path:sub(1, 1) == "~" then
        path = (os.getenv("HOME") or "/home/nithin") .. path:sub(2)
    end

    local f = io.open(path, "r")
    if not f then
        print("[bridge error] Could not open file: " .. path)
        return false
    end

    local block_stack = {}
    local current_block_name = nil
    local current_block_data = nil

    for line in f:lines() do
        local l = strip_comments(line)
        if l then
            -- Check for block start: section_name {
            local bname = l:match("^([a-zA-Z0-9_]+)%s*{$")
            if bname then
                local new_tbl = {}
                if #block_stack == 0 then
                    current_block_name = bname
                    current_block_data = new_tbl
                    table.insert(block_stack, { name = bname, data = new_tbl, is_root = true })
                else
                    local parent = block_stack[#block_stack]
                    parent.data[bname] = new_tbl
                    table.insert(block_stack, { name = bname, data = new_tbl, is_root = false })
                end
            elseif l == "}" then
                if #block_stack > 0 then
                    local closed = table.remove(block_stack)
                    if closed.is_root then
                        local rname = closed.name
                        local rdata = closed.data
                        if rname == "windowrule" or rname == "layerrule" or rname == "device" then
                            apply_rule(rname, rdata)
                        elseif rname == "animations" then
                            -- animations are processed via hl.curve and hl.animation
                        else
                            config_sections[rname] = rdata
                        end
                        current_block_name = nil
                        current_block_data = nil
                    end
                end
            else
                -- Inside a block
                if #block_stack > 0 then
                    local cur = block_stack[#block_stack].data
                    local root_name = block_stack[1].name

                    if root_name == "animations" then
                        -- Handle bezier curve
                        local b_name, b_coords = l:match("^bezier%s*=%s*([%w_]+)%s*,%s*(.+)$")
                        if b_name and b_coords then
                            local parts = split_commas(b_coords)
                            if #parts >= 4 then
                                pcall(function()
                                    hl.curve(b_name, {
                                        type = "bezier",
                                        points = {
                                            { tonumber(parts[1]), tonumber(parts[2]) },
                                            { tonumber(parts[3]), tonumber(parts[4]) }
                                        }
                                    })
                                end)
                            end
                        end

                        -- Handle animation directive
                        local a_leaf, a_args = l:match("^animation%s*=%s*([%w_]+)%s*,%s*(.+)$")
                        if a_leaf and a_args then
                            local parts = split_commas(a_args)
                            if #parts >= 3 then
                                local enabled = (parts[1] == "1" or parts[1] == "yes" or parts[1] == "true")
                                local speed = tonumber(parts[2]) or 5
                                local bezier = parts[3]
                                local style = parts[4]
                                pcall(function()
                                    local anim_spec = {
                                        leaf = a_leaf,
                                        enabled = enabled,
                                        speed = speed,
                                        bezier = bezier
                                    }
                                    if style and #style > 0 then
                                        anim_spec.style = style
                                    end
                                    hl.animation(anim_spec)
                                end)
                            end
                        end
                    else
                        -- Standard key = value inside block
                        local key, val = l:match("^([a-zA-Z0-9_:%.-]+)%s*=%s*(.+)$")
                        if key and val then
                            val = trim(resolve_vars(val))
                            if key:match("^col%.") then
                                local sub = key:match("^col%.(.+)$")
                                cur.col = cur.col or {}
                                cur.col[sub] = parse_color_gradient(val)
                            else
                                cur[key] = parse_value(val)
                            end
                        end
                    end
                else
                    -- Outside any block (top level directives)
                    -- Variable: $name = value
                    local vname, vval = l:match("^%$([%w_]+)%s*=%s*(.+)$")
                    if vname then
                        vval = trim(vval)
                        if vname == "terminal" and vval == "kitty" then
                            vval = "/usr/bin/kitty"
                        elseif vname == "fileManager" and vval == "dolphin" then
                            vval = "/usr/bin/dolphin"
                        end
                        vars[vname] = vval
                    end

                    -- Source: source = path
                    local src_path = l:match("^source%s*=%s*(.+)$")
                    if src_path then
                        src_path = trim(resolve_vars(src_path))
                        parse_file(src_path)
                    end

                    -- Monitor
                    local mon_str = l:match("^monitor%s*=%s*(.+)$")
                    if mon_str then
                        local parts = split_commas(mon_str)
                        if #parts >= 4 then
                            local out_name = parts[1] == "" and "eDP-1" or parts[1]
                            local mode_val = parts[2] == "" and "preferred" or parts[2]
                            local pos_val  = parts[3] == "" and "auto" or parts[3]
                            local scale_val = tonumber(parts[4]) or 1.2
                            pcall(function()
                                hl.monitor({
                                    output   = out_name,
                                    mode     = mode_val,
                                    position = pos_val,
                                    scale    = scale_val,
                                })
                            end)
                            monitor_loaded = true
                        end
                    end

                    -- Env
                    local ename, eval = l:match("^env%s*=%s*([%w_]+)%s*,%s*(.+)$")
                    if ename then
                        eval = trim(resolve_vars(eval))
                        if ename == "PATH" then
                            eval = sanitize_path(eval)
                        end
                        pcall(function() hl.env(ename, eval) end)
                    end

                    -- Gesture
                    local g_args = l:match("^gesture%s*=%s*(.+)$")
                    if g_args then
                        local parts = split_commas(g_args)
                        if #parts >= 3 then
                            pcall(function()
                                hl.gesture({
                                    fingers   = tonumber(parts[1]) or 3,
                                    direction = parts[2],
                                    action    = parts[3],
                                })
                            end)
                        end
                    end

                    -- Exec-once (Guaranteed to execute once per compositor session, never on reload or verify)
                    local exec_once_cmd = l:match("^exec%-once%s*=%s*(.+)$")
                    if exec_once_cmd then
                        local sig = os.getenv("HYPRLAND_INSTANCE_SIGNATURE")
                        if sig and #sig > 0 then
                            local lock_file = "/run/user/" .. tostring(os.getenv("UID") or "1000") .. "/hyprland-exec-once-" .. sig .. ".lock"
                            local lock = io.open(lock_file, "r")
                            if not lock then
                                exec_once_cmd = trim(resolve_vars(exec_once_cmd))
                                pcall(function() hl.exec_cmd(exec_once_cmd) end)
                            else
                                lock:close()
                            end
                        end
                    end

                    -- Bindings
                    local btype, bbody = l:match("^(bind[a-z]*)%s*=%s*(.+)$")
                    if btype and bbody then
                        local parts = split_commas(bbody)
                        local mods = parts[1] or ""
                        local key  = parts[2] or ""
                        local disp = parts[3] or ""
                        local arg  = ""
                        if #parts >= 4 then
                            local rest = {}
                            for i = 4, #parts do
                                if parts[i] ~= "" or i < #parts then
                                    table.insert(rest, parts[i])
                                end
                            end
                            arg = table.concat(rest, ", ")
                        end
                        register_binding(btype, mods, key, disp, arg)
                    end
                end
            end
        end
    end
    f:close()
    return true
end

-- Parse primary configuration file
parse_file(CONF_PATH)

-- Mark exec-once lock so reloads never re-spawn startup processes
local sig = os.getenv("HYPRLAND_INSTANCE_SIGNATURE")
if sig and #sig > 0 then
    local lock_path = "/run/user/" .. tostring(os.getenv("UID") or "1000") .. "/hyprland-exec-once-" .. sig .. ".lock"
    local lf = io.open(lock_path, "w")
    if lf then
        lf:write("initialized\n")
        lf:close()
    end
end

-- Apply all aggregated config sections (general, decoration, layouts, misc, input)
local cfg_ok, cfg_err = pcall(function()
    hl.config(config_sections)
end)
if not cfg_ok then
    error("[bridge] Configuration error: " .. tostring(cfg_err), 0)
end

-- Fallback monitor guarantee (eDP-1 at 1.2 scale) if not loaded from config
if not monitor_loaded then
    hl.monitor({
        output   = "eDP-1",
        mode     = "1920x1200@165",
        position = "0x0",
        scale    = 1.2,
    })
end

print("[bridge] Successfully loaded hyprland.conf into Hyprland")
